    "Component": [
      {
        "component_id": "comp_control_board",
        "name": "Control board",
        "description": "Circuit board mounted to the front panel; connects to the power board by a ribbon cable.",
        "category": "control"
      },
      {
        "component_id": "comp_compressor_driver_board",
        "name": "Compressor-driver board",
        "description": "Circuit board in the power supply connected to the MOSFET, diode, and wire connectors at J1, J2, and J3.",
        "category": "control"
      },
      {
        "component_id": "comp_power_board",
        "name": "Power board",
        "description": "Circuit board in the power supply, connected to the control board at J7 and to the TORCH START connector at J12.",
        "category": "electrical"
      },
      {
        "component_id": "comp_power_supply",
        "name": "Power supply",
        "description": "Assembly containing the control board, compressor-driver board, and power board.",
        "category": "electrical"
      },
      {
        "component_id": "comp_front_panel",
        "name": "Front panel",
        "description": "Panel that holds the control board and amperage adjustment knob.",
        "category": "panel"
      },
      {
        "component_id": "comp_heatsink",
        "name": "Heatsink",
        "description": "Heat-dissipating component supporting the compressor-driver board's MOSFET and diode through thermal strips.",
        "category": "thermal"
      },
      {
        "component_id": "comp_mosfet",
        "name": "MOSFET",
        "description": "Power semiconductor mounted on the compressor-driver board and positioned on a thermal strip over the heatsink.",
        "category": "electrical"
      },
      {
        "component_id": "comp_diode",
        "name": "Diode",
        "description": "Power semiconductor mounted on the compressor-driver board and positioned on a thermal strip over the heatsink.",
        "category": "electrical"
      },
      {
        "component_id": "comp_thermal_strips",
        "name": "Thermal strips",
        "description": "Strips applied to the heatsink beneath the compressor-driver board's MOSFET and diode.",
        "category": "thermal"
      }
    ],
